static void need(bool x,const std::string&m){if(!x)throw std::runtime_error(m);}
#include "historical_hazards.cpp"
static const std::array<unsigned,64> ranks=[](){std::array<unsigned,64>a{};unsigned rank=0;for(unsigned diagonal=0;diagonal<15;++diagonal)for(unsigned step=0;step<8;++step){int row=diagonal%2?int(step):7-int(step),col=int(diagonal)-row;if(col>=0&&col<8)a[unsigned(row*8+col)]=rank++;}return a;}();
template<size_t N>static uint32_t get(const VlWide<N>&v,unsigned at,unsigned bits){unsigned w=at/32,s=at%32;uint64_t x=v[w];if(s+bits>32)x|=uint64_t(v[w+1])<<32;return uint32_t(x>>s)&(bits==32?0xffffffffU:(uint32_t(1)<<bits)-1);}
static uint32_t get(uint64_t v,unsigned at,unsigned bits){return uint32_t(v>>at)&(bits==32?0xffffffffU:(uint32_t(1)<<bits)-1);}
static uint32_t position(uint32_t word){return ((word>>19)*64)+ranks[(word>>13)&63];}
struct Record{unsigned band,block,index;int value;};
struct Transaction{unsigned blocks;bool raw;std::array<std::vector<Record>,4> records;std::vector<int> gold;};
static Transaction packet(unsigned blocks,bool raw,unsigned salt){Transaction p{blocks,raw,{},std::vector<int>(blocks*64)};for(unsigned b=0;b<blocks;++b){int dc=int((b*977+salt)%4097)-2048;p.records[0].push_back({0,b,0,dc});p.gold[64*b]=dc;if(raw){for(unsigned i=1;i<64;++i){int v=int((b*251+i*557+salt)%4097)-2048;p.records[0].push_back({0,b,i,v});p.gold[b*64+i]=v;}}else for(unsigned i=1;i<64;++i){unsigned z=ranks[i];if((z+b+salt)%5==0||z==1||z==6||z==21){unsigned band=z<6?1:z<21?2:3;int v=int((b*337+i*331+salt)%4096)-2048;if(!v)v=1;p.records[band].push_back({band,b,i,v});p.gold[b*64+i]=v;}}}for(auto&v:p.records)std::sort(v.begin(),v.end(),[](const Record&a,const Record&b){return a.block*64+ranks[a.index]<b.block*64+ranks[b.index];});if(raw)std::sort(p.records[0].begin(),p.records[0].end(),[](const Record&a,const Record&b){return a.block*64+a.index<b.block*64+b.index;});return p;}
struct Counters{uint64_t edges=0,cache_checks=0,cache_events=0,live_reads=0,head_compares=0,requests=0,acks=0,dense=0,transactions=0;unsigned bankmask=0,offsetmask=0;};
static Counters totals;
class ProbeBench{public:
 Vscratch_probe d;std::mt19937 rng;std::ofstream&trace;std::array<uint8_t,262144> ram{};uint64_t clocks=0;unsigned epoch=0;bool pending=false,owner_write=false;uint32_t owner_addr=0,owner_epoch=0;std::array<uint32_t,4> owner_data{};unsigned delay=0;bool hold_ack=false,stale=false,rsp_error=false;int corrupt_bank=-1;bool injected=false;std::array<uint32_t,4> starts{};const Transaction*active=nullptr;unsigned outputs=0;bool verify_dense=true;
 ProbeBench(unsigned seed,std::ofstream&t):rng(seed),trace(t){d.clk=0;d.reset=1;d.begin_valid=0;d.begin_blocks=1;d.begin_raw=0;d.begin_serial_clear=0;d.begin_overlap=0;d.begin_prefetch=0;d.begin_tile_overlap=0;d.begin_count1=0;d.begin_count2=0;d.begin_count3=0;d.begin_epoch=0;d.coef_valid=0;d.coef_band=0;d.coef_block=0;d.coef_index=0;d.coef_value=0;d.coef_epoch=0;d.band_end_valid=0;d.band_end_band=0;d.band_end_epoch=0;d.seal_valid=0;d.seal_epoch=0;d.abort_valid=0;d.abort_epoch=0;d.dense_ready=0;d.mem_req_ready=0;d.mem_rsp_valid=0;d.mem_rsp_epoch=0;d.mem_rsp_error=0;for(unsigned j=0;j<4;++j)d.mem_rsp_data[j]=0;tick();d.reset=0;}
 void check(){need(!d.mismatch,"whole production scratch mismatch");for(unsigned bank=0;bank<4;++bank)if(d.debug_cache_valid&(1U<<bank)){totals.bankmask|=1U<<bank;for(unsigned off=0;off<16;++off){uint32_t word=0;for(unsigned byte=0;byte<4;++byte)if(off+byte<16)word|=get(d.verify_cache_data,bank*128+(off+byte)*8,8)<<(byte*8);need(get(d.verify_positions,(bank*16+off)*19,19)==position(word),"independent all-offset cache position");++totals.cache_checks;totals.offsetmask|=1U<<off;}}if(d.verify_position_use){need(d.verify_read_position==position(d.verify_read_word),"independent live record position");unsigned band=d.verify_read_band;need(band>=1&&band<=3,"live band range");if(get(d.verify_cursors,(band-1)*32,32)){need(get(d.verify_head_positions,(band-1)*19,19)==position(get(d.verify_heads,(band-1)*32,32)),"independent old-head position");}}}
 void cache_event(unsigned state){trace<<"{\"kind\":\"cache\",\"clock\":"<<totals.edges<<",\"state\":"<<state<<",\"valid\":"<<unsigned(d.debug_cache_valid)<<",\"data\":[";for(unsigned i=0;i<16;++i){if(i)trace<<',';trace<<d.verify_cache_data[i];}trace<<"],\"positions\":[";for(unsigned i=0;i<64;++i){if(i)trace<<',';trace<<get(d.verify_positions,i*19,19);}trace<<"]}\n";++totals.cache_events;}
 void tick(){need(++clocks<300000,"transaction watchdog");d.mem_req_ready=!pending&&rng()%4!=0;d.mem_rsp_valid=pending&&!hold_ack&&delay==0;d.mem_rsp_epoch=owner_epoch+unsigned(stale);d.mem_rsp_error=rsp_error;for(unsigned j=0;j<4;++j)d.mem_rsp_data[j]=owner_data[j];d.clk=0;d.eval();check();unsigned state=d.debug_state;bool kill=d.reset||(d.abort_valid&&d.abort_epoch==d.active_epoch);bool retired=d.mem_rsp_valid&&!stale;bool accepted=d.mem_req_valid&&d.mem_req_ready;bool cachewrite=!kill&&d.mem_rsp_valid&&!stale&&!rsp_error&&d.debug_outstanding&&(d.debug_prefetch_offer||(state==11&&d.debug_return_state!=12&&d.debug_return_state!=13));
  if(d.verify_position_use){trace<<"{\"kind\":\"read\",\"clock\":"<<totals.edges<<",\"address\":"<<d.verify_read_address<<",\"segment\":"<<unsigned(d.verify_read_segment)<<",\"band\":"<<unsigned(d.verify_read_band)<<",\"word\":"<<d.verify_read_word<<",\"position\":"<<d.verify_read_position<<",\"cursor\":"<<get(d.verify_cursors,(d.verify_read_band-1)*32,32)<<",\"head_word\":"<<get(d.verify_heads,(d.verify_read_band-1)*32,32)<<",\"head_position\":"<<get(d.verify_head_positions,(d.verify_read_band-1)*19,19)<<"}\n";++totals.live_reads;if(get(d.verify_cursors,(d.verify_read_band-1)*32,32))++totals.head_compares;}
  if(d.dense_valid&&d.dense_ready){if(verify_dense){need(active,"dense without transaction");need(d.dense_block==outputs/64&&d.dense_index==outputs%64&&d.dense_epoch==epoch,"dense tuple order/epoch");need(int16_t(d.dense_value)==active->gold[outputs],"independent dense value");}++outputs;++totals.dense;}
  if(accepted){need(!pending,"multiple memory owners");owner_write=d.mem_req_write;owner_addr=d.mem_req_addr;owner_epoch=d.mem_req_epoch;need(owner_addr%16==0&&owner_addr+16<=d.used_bytes,"request bounds");for(unsigned j=0;j<4;++j){owner_data[j]=d.mem_req_data[j];if(!owner_write){owner_data[j]=0;for(unsigned k=0;k<4;++k)owner_data[j]|=uint32_t(ram[owner_addr+j*4+k])<<(8*k);}}if(!owner_write&&corrupt_bank>=0&&!injected&&owner_addr>=starts[unsigned(corrupt_bank)]&&owner_addr<starts[unsigned(corrupt_bank)]+16){for(auto&v:owner_data)v=rng();injected=true;verify_dense=false;}delay=1+rng()%7;}
  d.clk=1;d.eval();check();d.clk=0;d.eval();check();if(cachewrite)cache_event(state);if(retired){need(pending,"response without owner");if(owner_write&&!rsp_error)for(unsigned j=0;j<4;++j)for(unsigned k=0;k<4;++k)ram[owner_addr+j*4+k]=uint8_t(owner_data[j]>>(k*8));pending=false;++totals.acks;}if(accepted){pending=true;++totals.requests;}else if(pending&&delay)--delay;++totals.edges;stale=false;rsp_error=false;
 }
 void wait(unsigned state){for(unsigned n=0;d.debug_state!=state;++n){need(n<5000,"state wait");tick();}}
 void ingest(const Transaction&p,unsigned profile){active=&p;verify_dense=true;outputs=0;epoch=1;d.begin_epoch=epoch;d.begin_blocks=p.blocks;d.begin_raw=p.raw;d.begin_serial_clear=profile&1;d.begin_overlap=(profile>>1)&1;d.begin_prefetch=(profile>>2)&1;d.begin_tile_overlap=(profile>>3)&1;d.begin_count1=p.records[1].size();d.begin_count2=p.records[2].size();d.begin_count3=p.records[3].size();starts[0]=32;starts[1]=32+((p.blocks*2+15)&~15U);starts[2]=starts[1]+((p.records[1].size()*4+15)&~15U);starts[3]=starts[2]+((p.records[2].size()*4+15)&~15U);d.begin_valid=1;d.eval();need(d.begin_ready,"new transaction not ready");tick();d.begin_valid=0;need(!d.error,"allocation failed");for(unsigned band=0;band<(p.raw?1U:4U);++band){for(const auto&r:p.records[band]){while(!d.coef_ready)tick();d.coef_band=band;d.coef_block=r.block;d.coef_index=r.index;d.coef_value=uint16_t(r.value);d.coef_epoch=epoch;d.coef_valid=1;tick();d.coef_valid=0;while(!d.coef_ready)tick();need(!d.error,"coefficient ingest rejected");}d.band_end_valid=1;d.band_end_band=band;d.band_end_epoch=epoch;tick();d.band_end_valid=0;if(band+1<(p.raw?1U:4U))wait(1);}while(!d.seal_ready)tick();d.seal_valid=1;d.seal_epoch=epoch;tick();d.seal_valid=0;}
 void finish(){for(unsigned n=0;!d.done&&!d.error;++n){need(n<100000,"completion watchdog");d.dense_ready=rng()%4!=0;tick();}need(d.done&&!d.error&&!pending,"transaction failed/drained");need(outputs==active->blocks*64,"dense output count");++totals.transactions;}
 void abort_and_drain(bool reset){d.reset=reset;d.abort_valid=!reset;d.abort_epoch=epoch;tick();d.reset=0;d.abort_valid=0;hold_ack=false;for(unsigned n=0;pending||d.busy;++n){need(n<1000,"cancel drain watchdog");tick();}need(d.begin_ready,"cancel did not idle");}
};
int main(int argc,char**argv){try{need(argc==3,"usage seed trace");unsigned seed=std::stoul(argv[1]);std::ofstream trace(argv[2]);need(bool(trace),"trace open");unsigned full=0,corrupt=0,owner=0;
 for(unsigned blocks:{1U,3U,8U})for(unsigned raw=0;raw<2;++raw)for(unsigned profile=0;profile<16;++profile){if(raw&&(profile&8))continue;auto p=packet(blocks,raw!=0,seed+profile);ProbeBench b(seed+full,trace);b.ingest(p,profile);b.finish();++full;}
 for(unsigned bank=0;bank<4;++bank)for(unsigned repeat=0;repeat<32;++repeat){auto p=packet(3,false,seed+repeat);ProbeBench b(seed+repeat*4+bank,trace);b.corrupt_bank=int(bank);b.ingest(p,6);for(unsigned n=0;!b.injected;++n){need(n<10000,"corrupt read not reached");b.tick();}while(b.pending)b.tick();b.tick();b.abort_and_drain(repeat&1);++corrupt;}
 for(unsigned action=0;action<4;++action){auto p=packet(3,false,seed+action);ProbeBench b(seed+action,trace);b.ingest(p,6);for(unsigned n=0;!(b.pending&&!b.owner_write);++n){need(n<10000,"owner read not reached");b.tick();}b.hold_ack=true;for(unsigned j=0;j<8;++j)b.tick();if(action<2)b.abort_and_drain(action!=0);else{while(b.delay)b.tick();b.hold_ack=false;if(action==2)b.stale=true;else b.rsp_error=true;b.tick();need(b.d.error==(action==2?6:5),"read response error priority");b.abort_and_drain(false);}++owner;}
 char*legacy_args[]={argv[0]};int legacy=historical_hazards_main(1,legacy_args);need(legacy==0,"historic accepted-write hazards");
 need(totals.bankmask==15&&totals.offsetmask==65535,"all-bank/all-offset coverage");std::cout<<"{\"type\":\"scratch_predecode_verdict\",\"status\":\"TEST_PASS\",\"seed\":"<<seed<<",\"full_transactions\":"<<full<<",\"corrupt_response_cases\":"<<corrupt<<",\"read_owner_cases\":"<<owner<<",\"clock_edges\":"<<totals.edges<<",\"cache_position_checks\":"<<totals.cache_checks<<",\"cache_events\":"<<totals.cache_events<<",\"live_reads\":"<<totals.live_reads<<",\"head_compares\":"<<totals.head_compares<<",\"requests\":"<<totals.requests<<",\"acks\":"<<totals.acks<<",\"dense_values\":"<<totals.dense<<",\"bank_mask\":"<<totals.bankmask<<",\"offset_mask\":"<<totals.offsetmask<<"}\n";return 0;
}catch(const std::exception&e){std::cerr<<"SCRATCH_PREFETCH_FAIL "<<e.what()<<'\n';return 1;}}
